\system{npend_3}
\defvar{theta0}{Angle}{rad}
\defvar{theta1}{Angle}{rad}
\defvar{theta2}{Angle}{rad}
\parameter{m}{1.0}{kg}
\parameter{l}{1.0}{m}
\parameter{g}{9.81}{m/s^2}
\lagrangian{(1.5*m*l^2*\cos{theta0 - theta0}*\dot{theta0}*\dot{theta0} + 1.0*m*l^2*\cos{theta0 - theta1}*\dot{theta0}*\dot{theta1} + 0.5*m*l^2*\cos{theta0 - theta2}*\dot{theta0}*\dot{theta2} + 1.0*m*l^2*\cos{theta1 - theta0}*\dot{theta1}*\dot{theta0} + 1.0*m*l^2*\cos{theta1 - theta1}*\dot{theta1}*\dot{theta1} + 0.5*m*l^2*\cos{theta1 - theta2}*\dot{theta1}*\dot{theta2} + 0.5*m*l^2*\cos{theta2 - theta0}*\dot{theta2}*\dot{theta0} + 0.5*m*l^2*\cos{theta2 - theta1}*\dot{theta2}*\dot{theta1} + 0.5*m*l^2*\cos{theta2 - theta2}*\dot{theta2}*\dot{theta2}) - (3.0*m*g*l*(1 - \cos{theta0}) + 2.0*m*g*l*(1 - \cos{theta1}) + 1.0*m*g*l*(1 - \cos{theta2}))}
\initial{theta0=0.3, theta0_dot=0.0, theta1=0.15, theta1_dot=0.0, theta2=0.15, theta2_dot=0.0}
